        queue<pair<int,int>>q;
        vector<vector<int>>ans(n, vector<int>(m,0));
        for(int i=0;i<n;i++){
            for(int j=0;j<m;j++){
                if(grid[i][j]==1){
                    q.push({i,j});
                    visited[i][j]=1;
                    ans[i][j] = 0;
                }
            }
        }
        int dist = 1;
        vector<int>delRows = {-1,0,1,0};
        vector<int>delCols = {0,1,0,-1};
        while(!q.empty()){
            int len = q.size();
            for(int i=0;i<len;i++){
                auto fr = q.front();
                q.pop();
                int r1=fr.first, c1=fr.second;
                for(int j=0;j<4;j++){
                    int r2=r1+delRows[j], c2=c1+delCols[j];
                    if(r2>=0 && c2>=0 && r2<n && c2<m){
                        if(ans[r2][c2]==0 && !visited[r2][c2]){
                            ans[r2][c2]=dist;
                            visited[r2][c2]=1;
                            q.push({r2,c2});
                        }
                    }
                }
            }
            dist++;
        }
        return ans;
    }
};
